import Label from "@/core/components/primitives/label/label";
import { useTranslation } from "react-i18next";
import { exhaustiveCheck, getDisplayState, multipleClassNames } from "@/core/helpers";

type VARIANT = "LABEL" | "SPAN";

type Props = {
  state: number;
  queueTimeText?: string;
  className?: string;
  variant?: VARIANT;
};

export const QueueTimeDisplay = ({ state, queueTimeText, className, variant = "LABEL" }: Props) => {
  const { t } = useTranslation();

  const displayState = getDisplayState(state, queueTimeText);

  switch (displayState) {
    case "STOPPAGE":
      return renderQueueTime(t("queueTimeStoppage"), variant, className);
    case "TIME_AVAILABLE":
      return renderQueueTime(`${t("queueTime")}: ${queueTimeText} ${t("queueMinutes")}`, variant, className);
    case "NO_TIME_AVAILABLE":
      return null; //If we for some reason don't get the time, we don't want to show anything
    default:
      return exhaustiveCheck(displayState);
  }
};

const renderQueueTime = (text: string, variant: VARIANT, className: string | undefined) => {
  switch (variant) {
    case "LABEL":
      return <Label title={text} />;
    case "SPAN":
      return <span className={multipleClassNames(className)}>{text}</span>;
    default:
      return exhaustiveCheck(variant);
  }
};
