import { Meta, StoryObj } from "@storybook/react";
import { QueueTimeDisplay } from "./queue-time-display";

const meta = {
  title: "Primitives/QueueTimeDisplay",
  component: QueueTimeDisplay,
  render: (args) => (
    //Position absolut is added just to make the component smaller in the storybook example
    //Actually, this component will grow to fit the parent container
    //But since we usually use this component on a card with position absolute, we to add it here as well to make it more realistic
    <div style={{ position: "absolute" }}>
      <QueueTimeDisplay {...args} />
    </div>
  ),
} satisfies Meta<typeof QueueTimeDisplay>;

export default meta;

type Story = StoryObj<typeof meta>;

export const WithTime: Story = {
  args: {
    queueTimeText: "0-10",
    state: 0,
  },
};

export const Error: Story = {
  args: {
    state: 1,
  },
};

export const NoTime: Story = {
  args: {
    state: 0,
    queueTimeText: undefined,
  },
  render(args) {
    return (
      <div>
        <p>No label should be visible here since we have no queueTimeText..</p>
        <QueueTimeDisplay {...args} />
      </div>
    );
  },
};
